"""The force-spectroscopy analysis on curves generated by the simulator's own force law."""
from __future__ import annotations

import numpy as np
import pytest

from stmbench.analysis.force import Curve, p5_numbers, short_range_df
from stmsim.physics.forces import ForceLaw, ForceParams, delta_f, force_truth

F0, K = 30e3, 1800.0
PARAMS = [ForceParams.from_yaml({"D_e_mev": de, "a_per_nm": a, "z_e_nm": ze, "hamaker_zj": 250.0,
                                 "z0_nm": 0.3, "bg_frac": bg})
          for de, a, ze, bg in ((80.0, 9.0, 0.30, 0.0), (220.0, 14.0, 0.34, 0.1), (280.0, 19.0, 0.38, 0.2))]


def _pair(p: ForceParams, amp: float, radius: float = 2e-9, offset_hz: float = 0.0):
    """Noise-free curves over the atom and over bare surface on one absolute height axis
    (mean tip height above the surface plane)."""
    h = np.linspace(0.25e-9, 1.3e-9, 512)
    on, off = ForceLaw(p, radius, w_lat=1.0), ForceLaw(p, radius, w_lat=0.0)
    df_on = delta_f(on.F, h - p.bump_m - amp, amp, F0, K) + offset_hz
    df_off = delta_f(off.F, h - amp, amp, F0, K) + offset_hz
    ok = h - p.bump_m - amp > 0.1e-9
    return Curve(h[ok], df_on[ok], h[ok] - h[ok][-1]), Curve(h, df_off, h - h[-1])


@pytest.mark.parametrize("p", PARAMS)
def test_the_chain_recovers_the_three_numbers_at_100_pm(p):
    atom, bare = _pair(p, 100e-12)
    got = p5_numbers([atom], [bare], f0=F0, k=K, amplitude=100e-12)
    t = force_truth(p, radius_m=2e-9, amplitude_m=100e-12, f0_hz=F0, k_n_per_m=K)
    # 100 pm is past the formula's weak spot for most decay lengths, not all: at a decay length
    # near 100 pm (the first set, 111 pm) it still reads ~5 % low
    assert got["f_min_pn"] == pytest.approx(t["f_min_pn"], rel=0.06)
    assert got["e_bind_mev"] == pytest.approx(t["e_bind_mev"], rel=0.06)
    assert got["f_decay_pm"] == pytest.approx(t["f_decay_pm"], rel=0.01)


def test_sader_jarvis_reads_low_when_the_amplitude_matches_the_decay_length():
    """The formula's known weak spot (Sader & Jarvis 2004): amplitudes comparable with the
    force's decay length. At 50 pm it reads the force minimum several per cent low; the decay
    length, a slope, is unaffected. Pinned so that tolerances keep room for it."""
    errs = []
    for p in PARAMS:
        atom, bare = _pair(p, 50e-12)
        got = p5_numbers([atom], [bare], f0=F0, k=K, amplitude=50e-12)
        t = force_truth(p, radius_m=2e-9, amplitude_m=50e-12, f0_hz=F0, k_n_per_m=K)
        errs.append(got["f_min_pn"] / t["f_min_pn"] - 1.0)
        assert got["f_decay_pm"] == pytest.approx(t["f_decay_pm"], rel=0.01)
    assert -0.10 < float(np.mean(errs)) < -0.03, errs


def test_a_frequency_offset_cancels_and_a_jump_in_one_curve_does_not_survive():
    p = PARAMS[1]
    atom, bare = _pair(p, 100e-12)
    ref = p5_numbers([atom], [bare], f0=F0, k=K, amplitude=100e-12)
    # the PLL's frequency zero is wherever it was switched on: a constant on every curve
    a2, b2 = _pair(p, 100e-12, offset_hz=3.7)
    same = p5_numbers([a2], [b2], f0=F0, k=K, amplitude=100e-12)
    assert same["f_min_pn"] == pytest.approx(ref["f_min_pn"], rel=1e-6)
    # a 0.8 Hz frequency jump halfway through one of three repeats
    jumped = Curve(atom.z_abs, atom.df.copy(), atom.z_rel)
    jumped.df[jumped.df.size // 2:] += 0.8
    med = p5_numbers([atom, jumped, atom], [bare], f0=F0, k=K, amplitude=100e-12)
    assert med["f_min_pn"] == pytest.approx(ref["f_min_pn"], rel=1e-6)


def test_curves_that_do_not_overlap_in_height_are_refused():
    p = PARAMS[0]
    atom, bare = _pair(p, 100e-12)
    far = Curve(bare.z_abs + 5e-9, bare.df, bare.z_rel)
    with pytest.raises(ValueError, match="overlap"):
        short_range_df([atom], [far])
